import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Docker：安装连接、镜像与容器生命周期","description":"Docker 管理的是镜像、容器进程、网络和数据卷。先分清镜像内容、容器可写层与挂载数据，再学习 Compose 部署；发布和恢复时必须同时记录镜像版本、配置与卷的对应关系。","frontmatter":{"title":"Docker：安装连接、镜像与容器生命周期","description":"Docker 管理的是镜像、容器进程、网络和数据卷。先分清镜像内容、容器可写层与挂载数据，再学习 Compose 部署；发布和恢复时必须同时记录镜像版本、配置与卷的对应关系。","showdocs":{"topics":[{"id":"docker","title":"Docker","link":"/topics/docker/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Docker机制与应用理论课程","summary":"Docker 管理的是镜像、容器进程、网络和数据卷。先分清镜像内容、容器可写层与挂载数据，再学习 Compose 部署；发布和恢复时必须同时记录镜像版本、配置与卷的对应关系。","status":"active","related":[{"title":"Docker 操作与命令","link":"/systems/docker/plus/ecosystem/docker-general-general","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 常用命令与对象速查","link":"/systems/docker/commands","kind":"命令","scope":"general","audience":"general"},{"title":"Docker 排障：构建、退出、网络与存储","link":"/systems/docker/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Docker 排障：构建、退出、网络与存储 · 容器退出、网络与存储排障","link":"/systems/docker/troubleshooting-part-02","kind":"故障排查","scope":"general","audience":"general"},{"title":"Docker 排障：构建、退出、网络与存储 · 升级后数据归零的恢复与复盘","link":"/systems/docker/troubleshooting-part-03","kind":"故障排查","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Docker：构建、PID 1、网络与卷","link":"/systems/docker/base/intermediate/mechanisms"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Docker：构建、PID 1、网络与卷","link":"/systems/docker/base/intermediate/mechanisms"}},"headers":[],"relativePath":"systems/docker/base/basic/start.md","filePath":"systems/docker/base/basic/start.md"}'),r={name:"systems/docker/base/basic/start.md"};function i(n,e,c,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="docker-安装连接、镜像与容器生命周期" tabindex="-1">Docker：安装连接、镜像与容器生命周期 <a class="header-anchor" href="#docker-安装连接、镜像与容器生命周期" aria-label="Permalink to &quot;Docker：安装连接、镜像与容器生命周期&quot;">​</a></h1><p>Docker 管理的是镜像、容器进程、网络和数据卷。先分清镜像内容、容器可写层与挂载数据，再学习 Compose 部署；发布和恢复时必须同时记录镜像版本、配置与卷的对应关系。</p><h2 id="learning-path" tabindex="-1">按任务阅读 <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;按任务阅读 {#learning-path}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前任务</th><th>阅读内容</th><th>应掌握的结果</th></tr></thead><tbody><tr><td>认识环境与基本操作</td><td>本篇的环境前提、基本对象与操作</td><td>说明管理的对象、执行身份和配置位置</td></tr><tr><td>理解机制并完成配置</td><td><a href="/systems/docker/base/intermediate/mechanisms">构建、PID 1、网络与卷</a>；<a href="/systems/docker/plus/practice/application">Compose 双服务部署与持久数据</a></td><td>解释关键机制，按配置完成任务并核对结果</td></tr><tr><td>维护、排障与恢复</td><td><a href="/systems/docker/maintenance#part-1">镜像发布、备份恢复与升级</a>；<a href="/systems/docker/troubleshooting#part-2">容器退出、网络与存储排障</a>；<a href="/systems/docker/troubleshooting#part-3">升级后数据归零的恢复与复盘</a></td><td>能保存证据、控制变更、恢复并验收</td></tr></tbody></table><p>本课程只阅读和推演，不要求安装 Docker。示例未执行，文中的命令全部留给读者在自己的隔离环境决定是否运行。Compose 作为 Docker 内部编排能力讲解，不单列技术主题。</p><h2 id="environment" tabindex="-1">适用范围 <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;适用范围 {#environment}&quot;">​</a></h2><p>Docker 版本边界应按组件分别判断：本文采用 Linux 容器、Engine 的 OCI 镜像/容器模型、BuildKit Dockerfile frontend 1 与现代 Compose Specification；不把 Engine、Desktop、Buildx 和 Compose 的版本号混成一个版本。2026-10-17 核对官方机制文档，不宣称某个补丁号是当前 latest。示例基础镜像使用 Python 3.13 版本族的 slim 标签，标签可移动，读者发布时还需核对支持期、平台 manifest 和 digest。</p><p>Linux Engine 共享宿主 Linux 内核；Windows 使用 Docker Desktop 的 Linux 容器模式时，实际内核、卷路径与资源上限属于 Linux VM/WSL2 边界。Windows 容器镜像不是本例目标，Linux UID/GID、信号、权限与路径不能直接套到 Windows 容器。macOS 不纳入。课程不探测本机 Docker 版本。</p><h2 id="architecture" tabindex="-1">客户端与守护进程 <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;客户端与守护进程 {#architecture}&quot;">​</a></h2><p>Docker 客户端将请求发给选定 Context 的 Engine API，daemon 再借助 containerd/runc 管理进程。终端所在机器不必是容器所在机器；bind mount 的宿主路径属于 daemon 主机。把客户端当前目录与远程主机路径混为一谈，会产生“文件在本机存在却挂载失败”的假象。</p><p>镜像是配置与只读层的分发对象；容器是从镜像创建的运行配置、可写层和进程生命周期。容器停止不删除可写层，容器删除才丢失这部分状态；named volume 有独立生命周期。重启旧容器也不会自动换成刚拉取的新镜像。</p><h2 id="commands" tabindex="-1">命令的对象与影响 <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;命令的对象与影响 {#commands}&quot;">​</a></h2><p>Docker 命令阅读要先识别对象和影响：image inspect 看镜像元数据，container inspect 看实际容器配置，logs 看标准输出，compose ps 看项目实例。build 会执行构建步骤；pull、up、run、exec 会下载、创建或运行对象。compose config 展示解析后的配置模型，不能证明镜像可用或服务运行正常。</p><div class="language-bash vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 以下仅供读者未来自行使用，并非本轮执行记录</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/m5-docker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail=50</span></span></code></pre></div><p>运行前必须自己确认 Context、镜像来源、18080 端口占用、可写数据卷、构建网络与资源容量。完整文件及结果推演见<a href="/systems/docker/plus/practice/application">应用项目</a>。不要在仓库根目录构建本站应用的 Dockerfile；练习有自己的目录。</p><h2 id="exercise" tabindex="-1">练习与解答 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与解答 {#exercise}&quot;">​</a></h2><p>问题：远程 Context 下，为什么本机的 <code>/srv/config</code> 不能直接作为容器配置？答案：daemon 解释 bind mount 源路径，本机路径并不自动上传。应把配置纳入镜像、显式分发到 daemon 主机或选用受控配置管理，不能靠反复重启解决路径归属错误。</p><p>问题：删掉容器后计数是否保留？答案：只有写到本例 counter named volume 的 SQLite 数据保留；写到镜像之上的可写层的数据随容器删除。镜像备份也不包含卷数据。</p><h2 id="sources" tabindex="-1">深入手册与来源 <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;深入手册与来源 {#sources}&quot;">​</a></h2><p>既有<a href="/systems/docker/plus/subjects/01-version-and-architecture">版本与架构</a>、<a href="/systems/docker/installation#part-1">安装配置</a>保留了组件链路、Rootless、Context、daemon 与防火墙细节，适合按任务查阅。旧页 2026-08-12 的版本表只是当时快照，不作为本课程当前版本保证。</p><p>一手依据：<a href="https://docs.docker.com/get-started/docker-overview/" target="_blank" rel="noopener noreferrer">Docker 架构</a>、<a href="https://docs.docker.com/compose/intro/compose-application-model/" target="_blank" rel="noopener noreferrer">Compose 应用模型</a>。Docker 官方主要以英文维护；中文机制术语另与 Kubernetes 官方中文容器/工作负载文档交叉辨析，不能拿第三方 Docker 中文翻译作为版本事实。</p><h2 id="legacy-containers-compose-command-objects" tabindex="-1">按对象选择 Compose 操作 <a class="header-anchor" href="#legacy-containers-compose-command-objects" aria-label="Permalink to &quot;按对象选择 Compose 操作 {#legacy-containers-compose-command-objects}&quot;">​</a></h2><p>Compose 的 up、start、run 和 down 操作的对象有什么区别？ 阅读 Compose 命令时先分清配置模型、镜像产物和运行实例。旧命令表把 up、start、run 放在一起，容易掩盖它们的对象差别：up 协调服务配置并创建所需实例，start 面向已有但停止的容器，run 为一次性任务创建容器。build、pull、push 改变或传输镜像；ps、logs 帮助观察项目；config 展示解析后的模型，输出可能展开敏感变量，不能直接公开。pause/unpause 暂停或恢复进程，不能当成数据一致备份。现代命令写作 docker compose；旧 docker-compose 的 scale 拼法和旧 YAML version 标记不作为当前操作合同。</p><p>停止、移除和清理数据也须分开。stop 保留容器，rm 面向停止的容器，down 还会清理项目所管理的容器和网络；是否涉及卷取决于选项与对象归属。对本文计数项目，应先明确 counter 卷是否需要保留，再决定清理范围。不要将“列表删除”中的命令替换直接用于共享主机。这里只解释操作影响，没有运行任何命令。<a href="https://docs.docker.com/reference/compose-file/services/" target="_blank" rel="noopener noreferrer">Compose 服务定义</a>与<a href="https://docs.docker.com/compose/how-tos/networking/" target="_blank" rel="noopener noreferrer">网络生命周期</a>是核对入口（2026-10-17）。</p>`,24)])])}const m=s(r,[["render",i]]);export{h as __pageData,m as default};
